  font-size: 0.85rem;
  text-align: center;
}

.block {
  display: flex;
  gap: var(--seat-gap);
  flex-shrink: 0;

  // Columns 1–4 and 21–24: four seat widths.
  &.outer {
    width: calc(4 * var(--seat-size) + 3 * var(--seat-gap));
  }

  // Columns 5–20: sixteen seat widths.
  &.inner {
    width: calc(16 * var(--seat-size) + 15 * var(--seat-gap));
  }
}

.aisle {
  width: calc(2 * var(--seat-size));
  flex-shrink: 0;
}

.seat,
.couch {
  height: var(--seat-size);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px 6px 4px 4px;
  color: #ffffff;
  font: inherit;
  font-size: 0.75rem;
  line-height: 1;
  cursor: pointer;

  &:disabled {
    cursor: not-allowed;
  }
}

.seat {
  width: var(--seat-size);
}

// A couch covers two columns, so it is two seat widths plus the gap between them.
.couch {
  width: calc(2 * var(--seat-size) + var(--seat-gap));
  border-radius: 12px 12px 4px 4px;
}

// Colours are fixed per state; hover and focus leave the background unchanged.
.seat[data-state='available'],
.couch[data-state='available'] {
  background-color: #2e7d32;
}

.seat[data-state='selected'],
.couch[data-state='selected'] {
  background-color: #f9a825;
  color: #212121;
}

.seat[data-state='unavailable'],
.couch[data-state='unavailable'] {
  background-color: #c62828;
}

.seat[data-state='accessible'] {
  background-color: #1565c0;
}

